  }
  bytesCount += 3 + object.assignedLevelIds.length * 3;
  {
    for (var i = 0; i < object.assignedLevelIds.length; i++) {
      final value = object.assignedLevelIds[i];
      bytesCount += value.length * 3;
    }
  }
  bytesCount += 3 + object.code.length * 3;
  bytesCount += 3 + object.color.length * 3;
  bytesCount += 3 + object.departmentId.length * 3;
  bytesCount += 3 + object.description.length * 3;
  bytesCount += 3 + object.name.length * 3;
  bytesCount += 3 + object.subjectId.length * 3;
